/**
 * Link version 3, frozen: the scenario channels.
 *
 * Written out as concrete types, copied from the shapes the app resolved when link version 3 was cut. It never
 * references the living types, so a change to a handler cannot move it. Do not edit this file to match a changed
 * handler: a change that breaks it needs a new LINK_VERSION and a new `contract/v<N>/` (see protocol.ts for the
 * rule). `tests/remote/contractV3.test.ts` checks the living types against it.
 */

import type {
    ScenarioDocumentV3,
    ScenarioIssueV3,
    ScenarioOverlayStatusV3,
    ScenarioStateV3,
    SimulationAssumptionsV3,
    SimulationDeadlineV3,
    SimulationEventV3,
    SimulationOperationV3,
    SimulationRequestV3,
    SimulationSubjectV3,
} from './shapesScenarios';
import type {
    ControlRecordV3,
    EffectiveValueV3,
    InstallationExecutorV3,
    InstallationV3,
    LifecycleFailureV3,
    ScenarioCapabilityRowV3,
    SnapshotBodyV3,
} from './shapesLifecycle';

export type ScenariosChannelsV3 = {
    'check-scenario': {
        args: [doc: unknown];
        result:
            | { success: false; error: string; issues?: undefined }
            | { success: false; error: string; issues: ScenarioIssueV3[] }
            | { success: true };
    };
    'delete-scenario': {
        args: [name: string];
        result: { success: true; error?: undefined } | { success: false; error: string };
    };
    'dry-run-scenario': {
        args: [challengeId: string | number];
        result:
            | { success: false; error: string; issues?: ScenarioIssueV3[] }
            | {
                  success: true;
                  scenario: string;
                  phase: string;
                  started: boolean;
                  halted: null | string;
                  manualOnly: boolean;
                  fire: null | { ruleId: string; startIndex: number; actions: string[] };
                  explain: { ruleId: string; label: string; status: 'ready' | 'blocked' | 'waiting'; reason: string }[];
                  nextWakeAt: null | number;
              };
    };
    'export-scenario': {
        args: [name: string];
        result:
            | { success: false; error: string; issues?: undefined }
            | { success: false; error: string; json?: undefined; omitted?: undefined }
            | { success: true; json: string; omitted: string[]; error?: undefined };
    };
    'get-scenario-status': {
        args: [challengeId: string | number];
        result:
            | { success: false; error: string; issues?: undefined }
            | {
                  serviceRuns: boolean;
                  manualOnly: boolean;
                  assigned: string;
                  scenario: null | ScenarioDocumentV3;
                  state: null | ScenarioStateV3;
                  corrupt: false | 'file' | 'record' | 'unloaded';
                  timezone: string;
                  overlay: ScenarioOverlayStatusV3;
                  success: true;
              };
    };
    'preview-scenario-import': {
        args: [text: string];
        result:
            | { success: false; error: string; issues?: undefined }
            | { success: false; error: string; issues: ScenarioIssueV3[] }
            | {
                  preview: {
                      name: string;
                      description: string;
                      start: string;
                      phases: { name: string; settings: string[]; rules: number }[];
                      spending: { phase: string; rule: undefined | string; action: string }[];
                      flagged: { phase: string; key: 'chosenPhotos' | 'chosenPhotosOnly' }[];
                      limits: { swaps?: number; keys?: number; fills?: number };
                  };
                  scenario: ScenarioDocumentV3;
                  exists: boolean;
                  success: true;
              };
    };
    'rename-scenario': {
        args: [oldName: string, newName: string];
        result:
            | { success: false; error: string; issues?: undefined }
            | { success: false; error: string; issues: ScenarioIssueV3[] }
            | { name: string; success: true };
    };
    'reset-scenario-state': {
        args: [challengeId: string | number];
        result: { success: false; error: string } | { success: true; error?: undefined };
    };
    'save-scenario': {
        args: [doc: unknown, options?: undefined | null | { overwrite?: boolean }];
        result:
            | { success: false; error: string; issues?: undefined }
            | { success: false; error: string; issues: ScenarioIssueV3[] }
            | { name: string; success: true };
    };
    'simulate-scenario': {
        args: [request: SimulationRequestV3];
        result:
            | { success: false; error: string; issues?: ScenarioIssueV3[] }
            | {
                  success: true;
                  scenario: string;
                  subject: SimulationSubjectV3;
                  now: number;
                  until: number;
                  manualOnly: boolean;
                  events: SimulationEventV3[];
                  assumptions: SimulationAssumptionsV3;
                  diagnostics: { key: string; value: string | number | boolean | null; provenance: string }[];
                  deadlines: SimulationDeadlineV3[];
                  finalState: ScenarioStateV3 | null;
                  stopReason: 'horizon' | 'idle' | 'needsEvidence' | 'halted' | 'limit';
                  stoppedAt: number;
                  passes: number[];
                  needs: { operation: SimulationOperationV3; subject: string; at: number } | null;
                  halted: string | null;
              };
    };
    // --- the installation scenario, the lifecycle of an assignment, pools, projections and the control inbox ---
    'get-scenario-capabilities': {
        args: [];
        result:
            | LifecycleFailureV3
            | {
                  success: true;
                  capabilities: {
                      settings: ScenarioCapabilityRowV3[];
                      remoteEnabled: Omit<ScenarioCapabilityRowV3, 'key'>;
                  };
              };
    };
    'get-scenario-snapshot': { args: [subject: string | number]; result: LifecycleFailureV3 | SnapshotBodyV3 };
    'get-installation-scenario': {
        args: [];
        result: LifecycleFailureV3 | { success: true; installation: InstallationV3 | null; generation: number | null };
    };
    'list-simulation-subjects': {
        args: [kind: 'candidate' | 'active' | 'completed'];
        result: LifecycleFailureV3 | { success: true; readable: boolean; subjects: { id: string; label: string }[] };
    };
    'get-effective-installation-settings': {
        args: [];
        result:
            | LifecycleFailureV3
            | {
                  success: true;
                  revision: number;
                  subject: 'installation';
                  generation: number | null;
                  values: { [key: string]: EffectiveValueV3 };
              };
    };
    'get-effective-presentation': {
        args: [];
        result:
            | LifecycleFailureV3
            | {
                  success: true;
                  revision: number;
                  available: boolean;
                  theme: string | null;
                  language: string | null;
                  reason: string | null;
              };
    };
    'get-stop-status': {
        args: [];
        result:
            | LifecycleFailureV3
            | {
                  success: true;
                  fence:
                      | {
                            state: 'ok';
                            stopEpoch: number;
                            blocked: boolean;
                            lastStop: { requestId: string; at: number; durable: boolean } | null;
                            lastArm: { epoch: number; at: number } | null;
                        }
                      | { state: 'missing' }
                      | { state: 'unreadable'; reason: 'not-loaded' | 'oversize' | 'malformed' | 'read-failed' };
                  durable: boolean | null;
                  ownerAcknowledged: boolean | null;
              };
    };
    'get-photo-pools': { args: []; result: LifecycleFailureV3 | { success: true; pools: { [key: string]: string[] } } };
    'get-effective-entry-pins': {
        args: [challengeId: string | number];
        result: LifecycleFailureV3 | { success: true; pins: { boost: null | string; turbo: null | string } };
    };
    'get-scenario-request-status': {
        args: [query: { requestId: string } | { target: string }];
        result:
            | LifecycleFailureV3
            | { success: true; state: 'unknown' }
            | { success: true; state: 'not-recorded' }
            | { success: true; state: 'request'; record: ControlRecordV3 }
            | {
                  success: true;
                  state: 'target';
                  target: string;
                  revision: number;
                  pending: ControlRecordV3 | null;
                  results: ControlRecordV3[];
              };
    };
    'set-installation-scenario': {
        args: [name: string | null, executor: InstallationExecutorV3, expectedGeneration: number];
        result: LifecycleFailureV3 | { success: true; installation: InstallationV3 | null; generation: number };
    };
    'pause-scenario': {
        args: [subject: string | number, reason?: string];
        result: LifecycleFailureV3 | { success: true; paused: boolean };
    };
    'resume-scenario': {
        args: [subject: string | number];
        result: LifecycleFailureV3 | { success: true; paused: boolean };
    };
    'handoff-scenario': {
        args: [subject: string | number, to: string, expectedGeneration: number];
        result: LifecycleFailureV3 | { success: true; generation: number };
    };
    'clear-scenario-assignment': {
        args: [subject: string | number, expectedGeneration: number];
        result: LifecycleFailureV3 | { success: true; generation: number };
    };
    'set-photo-pool': {
        args: [name: string, ids: string[]];
        result: LifecycleFailureV3 | { success: true };
    };
    'delete-photo-pool': { args: [name: string]; result: LifecycleFailureV3 | { success: true } };
    'rename-photo-pool': { args: [from: string, to: string]; result: LifecycleFailureV3 | { success: true } };
};
